//! The `rmcp::ServerHandler`, hand-written rather than generated by
//! rmcp's `#[tool]` macros, which want one Rust function per tool: with
//! 60-odd tools built from one clap tree that would mean writing the CLI a
//! second time. `list_tools`/`call_tool` read `registry::tools()` instead.

use std::collections::HashMap;
use std::future::Future;
use std::sync::Arc;

use gitpoulpi_config::{DefaultBackend, McpConfig};
use rmcp::model::{
    CallToolRequestParams, CallToolResult, ContentBlock, ErrorData as McpError, ListToolsResult,
    PaginatedRequestParams, ServerCapabilities, ServerInfo, Tool, ToolAnnotations,
};
use rmcp::service::{NotificationContext, RequestContext, RoleServer};
use rmcp::ServerHandler;
use serde_json::json;
use tokio::sync::Mutex;

use crate::registry::{self, ToolSpec};
use crate::{argv, policy};

/// Tool names whose real-world effect touches things outside this
/// process/repository - anything that talks to a git remote, an LFS server,
/// a hosting provider or an AI provider - get `open_world_hint: true`;
/// everything else defaults to the MCP spec's own default (`false`, a
/// closed local domain).
fn is_open_world(name: &str) -> bool {
    matches!(
        name,
        "fetch"
            | "pull"
            | "push"
            | "rewrite_push"
            | "clone"
            | "tag_push"
            | "tag_delete_remote"
            | "tag_delete"
            | "tag_fetch"
            | "branch_delete_remote"
            | "lfs_fetch"
            | "lfs_pull"
            | "lfs_push"
            | "lfs_lock"
            | "lfs_unlock"
            | "lfs_locks"
            | "submodule_update"
            | "ai_commit_message"
            | "ai_explain"
            | "ai_resolve_conflict"
            | "ai_split_plan"
            | "ai_rewrite_script"
            | "ai_rewrite_rules"
            | "hosting_edit_url"
            | "flow_start"
            | "flow_finish"
            | "flow_issue_new"
            | "flow_issue_wait"
            | "flow_pick_up"
            | "hosting_clone"
            | "hosting_pr"
            | "hosting_issue_create"
            | "hosting_projects"
            | "hosting_ssh_key_list"
            | "hosting_ssh_key_delete"
            | "hosting_integrations_test"
            | "hosting_prs"
            | "hosting_radar"
            | "hosting_pr_for_branch"
            | "hosting_file"
            | "hosting_review_show"
            | "hosting_review_diff"
            | "hosting_review_threads"
            | "hosting_review_comment"
            | "hosting_review_reply"
            | "hosting_review_resolve"
            | "hosting_review_submit"
            | "hosting_review_fetch"
            | "hosting_review_push"
            | "hosting_review_submit_change"
            | "hosting_review_abandon"
            | "hosting_review_suggest"
            | "hosting_checkout_pr"
            | "hosting_issues"
            | "hosting_board_show"
            | "hosting_board_move"
            | "hosting_issue_options"
            | "hosting_issue_edit"
            | "hosting_pr_edit"
            | "hosting_members"
            | "hosting_labels"
            | "hosting_milestones"
    )
}

/// The `ai_*` tools: listed only while `ai.enabled` is on (read live from
/// `config.toml`, so flipping it in Settings shows or hides them at the
/// next `tools/list`). A call to a hidden one still reaches the command,
/// which refuses with "AI is turned off".
fn is_ai_tool(name: &str) -> bool {
    name.starts_with("ai_")
}

fn ai_enabled() -> bool {
    gitpoulpi_config::Settings::resolve_ambient()
        .map(|s| s.config().ai.enabled)
        .unwrap_or(false)
}

pub struct GitPoulpiServer {
    ipc: Mutex<gitpoulpi_commands::Session>,
    session: String,
    backend: DefaultBackend,
    cfg: McpConfig,
    tools: HashMap<String, Arc<ToolSpec>>,
}

impl GitPoulpiServer {
    /// Connects (publishing its port, like the TUI - see
    /// `gitpoulpi_commands::client::Session::connect`) and builds the
    /// tool registry once, up front, rather than on every `list_tools`.
    pub async fn connect(
        session: String,
        backend: DefaultBackend,
        cfg: McpConfig,
    ) -> Result<Self, String> {
        crate::ensure_enabled(&cfg)?;
        let ipc = gitpoulpi_commands::Session::connect(&session, None, backend, true).await?;
        crate::update_watch::spawn(&session);
        let tools = registry::tools()
            .into_iter()
            .map(|spec| (spec.name.clone(), Arc::new(spec)))
            .collect();
        Ok(Self {
            ipc: Mutex::new(ipc),
            session,
            backend,
            cfg,
            tools,
        })
    }

    fn to_mcp_tool(&self, spec: &ToolSpec) -> Tool {
        let schema = spec.input_schema.as_object().cloned().unwrap_or_default();
        let mut tool = Tool::new(spec.name.clone(), spec.description.clone(), schema);
        tool.annotations = Some(
            ToolAnnotations::new()
                .read_only(spec.read_only)
                .destructive(spec.destructive)
                .idempotent(spec.idempotent),
        );
        if let Some(a) = tool.annotations.as_mut() {
            a.open_world_hint = Some(is_open_world(&spec.name));
        }
        tool
    }

    async fn handle_call(
        &self,
        params: CallToolRequestParams,
        client: Option<String>,
    ) -> Result<CallToolResult, McpError> {
        let name = params.name.to_string();
        let Some(spec) = self.tools.get(&name) else {
            return Err(McpError::invalid_params(
                format!("unknown tool `{name}`"),
                None,
            ));
        };

        if let Err(message) = policy::allowed(spec, &self.cfg) {
            return Ok(refusal(message));
        }

        let args = params.arguments.unwrap_or_default();
        let argv = match argv::to_argv(spec, &args) {
            Ok(argv) => argv,
            Err(message) => return Err(McpError::invalid_params(message, None)),
        };
        let cli = match argv::parse(&argv) {
            Ok(cli) => cli,
            Err(message) => return Err(McpError::invalid_params(message, None)),
        };

        // A per-call `session` different from the one this server connected
        // to would mean a different daemon than `self.ipc`; not supported
        // (see docs/user/mcp-and-agents.md), so it is refused rather than
        // silently ignored.
        // `show --raw` streams bytes to stdout or writes a file the caller
        // names: neither belongs in an agent's tool call.
        if matches!(
            cli.command,
            Some(gitpoulpi_commands::cli::Commands::Show { raw: true, .. })
        ) {
            return Ok(refusal(
                "`show --raw` is not available over MCP; use `show` (its JSON carries \
                 the image format and dimensions)"
                    .to_string(),
            ));
        }
        if let Some(requested) = &cli.session {
            let sanitised = gitpoulpi_config::sanitize_session_name(requested);
            if sanitised != self.session {
                return Ok(refusal(format!(
                    "this server is connected to session `{}`; per-call `session` \
                     (`{requested}`) isn't supported yet - start a second `mcp serve` for \
                     another session",
                    self.session
                )));
            }
        }

        let origin = gitpoulpi_ipc::ui::UiOrigin {
            client: client.unwrap_or_else(|| "mcp".to_string()),
            label: None,
            // The operator's choice (config or `--ui-control`), never an
            // argument the agent can pass: it travels with every intent so
            // the user's window can honour it.
            control: self.cfg.ui_control,
        };
        let mut ipc = self.ipc.lock().await;
        ipc.set_ui_origin(origin.clone());
        let result = gitpoulpi_commands::execute(&mut ipc, cli, &self.session).await;
        let result = match result {
            Err(message) if message.contains("daemon connection lost") => {
                // One reconnect attempt: the embedded daemons this
                // process's clients start don't publish, so a lost
                // connection is unrecoverable without starting a fresh
                // one -- see `Session::connect`'s doc comment.
                match gitpoulpi_commands::Session::connect(&self.session, None, self.backend, true)
                    .await
                {
                    Ok(fresh) => {
                        *ipc = fresh;
                        ipc.set_ui_origin(origin);
                        let argv = match argv::to_argv(spec, &args) {
                            Ok(argv) => argv,
                            Err(message) => return Err(McpError::invalid_params(message, None)),
                        };
                        let cli = match argv::parse(&argv) {
                            Ok(cli) => cli,
                            Err(message) => return Err(McpError::invalid_params(message, None)),
                        };
                        gitpoulpi_commands::execute(&mut ipc, cli, &self.session).await
                    }
                    Err(e) => Err(e),
                }
            }
            other => other,
        };

        match result {
            // A refused undo/redo: the typed refusal is the structured
            // content, and the call is an error so an agent notices.
            Ok(emitted) if emitted.exit_code != 0 => {
                let pretty = serde_json::to_string_pretty(&emitted.json)
                    .unwrap_or_else(|_| emitted.json.to_string());
                let mut result = CallToolResult::error(vec![ContentBlock::text(pretty)]);
                result.structured_content = Some(emitted.json);
                Ok(result)
            }
            Ok(emitted) => {
                let pretty = serde_json::to_string_pretty(&emitted.json)
                    .unwrap_or_else(|_| emitted.json.to_string());
                let mut result = CallToolResult::success(vec![ContentBlock::text(pretty)]);
                result.structured_content = Some(emitted.json);
                Ok(result)
            }
            Err(message) => Ok(refusal(message)),
        }
    }
}

fn refusal(message: String) -> CallToolResult {
    // A backend failure also carries what ran and what the tool printed, so
    // an agent can explain it instead of repeating "failed".
    let detail = gitpoulpi_commands::client::error_detail_for(&message);
    let mut text = message.clone();
    if let Some(detail) = &detail {
        for line in detail.lines() {
            text.push_str("\n  ");
            text.push_str(&line);
        }
    }
    let mut result = CallToolResult::error(vec![ContentBlock::text(text)]);
    let mut structured = json!({ "error": message });
    if let Some(detail) = detail {
        structured["detail"] = serde_json::to_value(detail).unwrap_or_default();
    }
    result.structured_content = Some(structured);
    result
}

/// A cheaply cloneable handle on one [`GitPoulpiServer`], so every
/// session of the HTTP transport shares the one daemon connection the
/// stdio transport would own.
#[derive(Clone)]
pub struct SharedServer(pub Arc<GitPoulpiServer>);

impl ServerHandler for SharedServer {
    fn get_info(&self) -> ServerInfo {
        self.0.get_info()
    }

    fn list_tools(
        &self,
        request: Option<PaginatedRequestParams>,
        context: RequestContext<RoleServer>,
    ) -> impl Future<Output = Result<ListToolsResult, McpError>> + Send + '_ {
        self.0.list_tools(request, context)
    }

    fn get_tool(&self, name: &str) -> Option<Tool> {
        self.0.get_tool(name)
    }

    fn call_tool(
        &self,
        request: CallToolRequestParams,
        context: RequestContext<RoleServer>,
    ) -> impl Future<Output = Result<CallToolResult, McpError>> + Send + '_ {
        self.0.call_tool(request, context)
    }
}

impl ServerHandler for GitPoulpiServer {
    fn get_info(&self) -> ServerInfo {
        let mut info = ServerInfo::default();
        info.capabilities = ServerCapabilities::builder().enable_tools().build();
        // `Implementation::from_build_env()`'s `env!("CARGO_CRATE_NAME")`
        // resolves inside `rmcp`'s own source, not ours, so it would
        // otherwise report "rmcp" here -- set explicitly instead.
        info.server_info.name = "gitpoulpi-mcp".to_string();
        info.server_info.version = env!("CARGO_PKG_VERSION").to_string();
        info.instructions = Some(
            "GitPoulpi: a GitBackend-mirroring tool per gitpoulpi CLI subcommand, run \
             through the same daemon a TUI on this repository would use. Reads always run; \
             mutations are gated by config.toml's [mcp] table."
                .to_string(),
        );
        info
    }

    fn list_tools(
        &self,
        _request: Option<PaginatedRequestParams>,
        _context: RequestContext<RoleServer>,
    ) -> impl Future<Output = Result<ListToolsResult, McpError>> + Send + '_ {
        let ai_on = ai_enabled();
        let mut specs: Vec<&Arc<ToolSpec>> = self
            .tools
            .values()
            .filter(|s| ai_on || !is_ai_tool(&s.name))
            .filter(|s| !policy::hidden(s, &self.cfg))
            .collect();
        specs.sort_by(|a, b| a.name.cmp(&b.name));
        let tools = specs.into_iter().map(|s| self.to_mcp_tool(s)).collect();
        std::future::ready(Ok(ListToolsResult::with_all_items(tools)))
    }

    fn get_tool(&self, name: &str) -> Option<Tool> {
        self.tools
            .get(name)
            .filter(|s| ai_enabled() || !is_ai_tool(&s.name))
            .filter(|s| !policy::hidden(s, &self.cfg))
            .map(|s| self.to_mcp_tool(s))
    }

    fn call_tool(
        &self,
        request: CallToolRequestParams,
        context: RequestContext<RoleServer>,
    ) -> impl Future<Output = Result<CallToolResult, McpError>> + Send + '_ {
        let client = context
            .peer
            .peer_info()
            .map(|info| info.client_info.name.clone());
        self.handle_call(request, client)
    }

    fn on_initialized(
        &self,
        _context: NotificationContext<RoleServer>,
    ) -> impl Future<Output = ()> + Send + '_ {
        std::future::ready(())
    }
}

